import React, { useEffect, useState } from "react";
import AdminNavbar from "../Components/AdminNavbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/AdminPages.css";

const Reports = () => {
  const [reports, setReports] = useState([]);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/admin/reports`)
      .then((res) => res.json())
      .then((data) => {
        if (Array.isArray(data)) {
          setReports(data);
        }
      })
      .catch((err) => console.error("Failed to fetch reports:", err));
  }, []);

  return (
    <>
      <AdminNavbar />
      <div className="admin-wrapper">
        <h2 className="admin-title">User Reports</h2>

        {reports.length === 0 ? (
          <p>No user reports submitted.</p>
        ) : (
          <div className="reports-grid">
            {reports.map((report) => (
              <div key={report.id} className="report-card">
                <p><strong>Reported User:</strong> {report.reported_username}</p>
                <p><strong>Reason:</strong> {report.reason}</p>
                <p><strong>Submitted By:</strong> {report.reporter_username}</p>
                <p><small>{new Date(report.created_at).toLocaleString()}</small></p>
              </div>
            ))}
          </div>
        )}
      </div>
      <Footer />
    </>
  );
};

export default Reports;
